#include <map>
#include <string>
#include <utility>
#include <vector>

std::string checkPath(int startIrql, const std::vector<std::string>& ops)
{
    static const std::map<std::string, int> maxIrql{
        { "ExAllocatePool2Paged", 1 }, { "ExAllocatePool2NonPaged", 2 }, { "ZwCreateFile", 0 }, { "KeSetEvent", 2 },
        { "IoCompleteRequest", 2 }, { "KeWaitForSingleObject", 1 }, { "RtlCopyMemory", 31 } };
    int irql{ startIrql };
    std::vector<std::pair<std::string, int>> saved;            // kind, previous IRQL
    auto at = [](std::size_t i, const std::string& m) { return "step " + std::to_string(i + 1) + ": " + m; };
    auto over = [&](std::size_t i, const std::string& what, int max) { return at(i, what + " at IRQL " + std::to_string(irql) + " (max " + std::to_string(max) + ")"); };

    for (std::size_t i{ 0 }; i < ops.size(); ++i)
    {
        const std::string& op{ ops[i] };
        if (op.rfind("raise ", 0) == 0)
        {
            const int to{ std::stoi(op.substr(6)) };
            if (to < irql) return at(i, "raise to " + std::to_string(to) + " from " + std::to_string(irql));
            saved.push_back({ "raise", irql });
            irql = to;
        }
        else if (op == "lower" || op == "spin release" || op == "mutex release")
        {
            const std::string kind{ op == "lower" ? "raise" : op == "spin release" ? "spin" : "mutex" };
            if (saved.empty() || saved.back().first != kind) return at(i, "release without acquire");
            irql = saved.back().second;
            saved.pop_back();
        }
        else if (op == "spin acquire")
        {
            if (irql > 2) return over(i, "spin acquire", 2);
            saved.push_back({ "spin", irql });
            irql = 2;
        }
        else if (op == "mutex acquire")
        {
            if (irql > 1) return over(i, "mutex acquire", 1);
            saved.push_back({ "mutex", irql });
            irql = 1;
        }
        else if (op == "touch paged")
        {
            if (irql >= 2) return over(i, "touch paged", 1);
        }
        else if (op.rfind("call ", 0) == 0)
        {
            const auto it{ maxIrql.find(op.substr(5)) };
            if (it == maxIrql.end()) return at(i, "unknown operation");
            if (irql > it->second) return over(i, it->first, it->second);
        }
        else return at(i, "unknown operation");
    }
    if (!saved.empty()) return "end: " + std::to_string(saved.size()) + " lock(s) or raise(s) still held";
    if (irql != startIrql) return "end: IRQL " + std::to_string(irql) + ", expected " + std::to_string(startIrql);
    return "";
}

unitTests:
TEST("correct paths") {
    CHECK_EQ(checkPath(0, { "call ZwCreateFile", "spin acquire", "call ExAllocatePool2NonPaged", "call KeSetEvent", "spin release", "touch paged" }), std::string(""));
    CHECK_EQ(checkPath(0, { "mutex acquire", "call ExAllocatePool2Paged", "touch paged", "mutex release" }), std::string(""));
    CHECK_EQ(checkPath(2, { "call IoCompleteRequest", "raise 15", "call RtlCopyMemory", "lower" }), std::string(""));
}
TEST("too high") {
    CHECK_EQ(checkPath(0, { "spin acquire", "call ExAllocatePool2Paged", "spin release" }), std::string("step 2: ExAllocatePool2Paged at IRQL 2 (max 1)"));
    CHECK_EQ(checkPath(0, { "spin acquire", "touch paged" }), std::string("step 2: touch paged at IRQL 2 (max 1)"));
    CHECK_EQ(checkPath(2, { "call KeWaitForSingleObject" }), std::string("step 1: KeWaitForSingleObject at IRQL 2 (max 1)"));
    CHECK_EQ(checkPath(0, { "spin acquire", "mutex acquire" }), std::string("step 2: mutex acquire at IRQL 2 (max 1)"));
    CHECK_EQ(checkPath(1, { "call ZwCreateFile" }), std::string("step 1: ZwCreateFile at IRQL 1 (max 0)"));
}
TEST("unbalanced") {
    CHECK_EQ(checkPath(0, { "spin release" }), std::string("step 1: release without acquire"));
    CHECK_EQ(checkPath(0, { "mutex acquire", "spin release" }), std::string("step 2: release without acquire"));
    CHECK_EQ(checkPath(0, { "spin acquire", "call KeSetEvent" }), std::string("end: 1 lock(s) or raise(s) still held"));
    CHECK_EQ(checkPath(2, { "raise 1" }), std::string("step 1: raise to 1 from 2"));
    CHECK_EQ(checkPath(0, { "call Mystery" }), std::string("step 1: unknown operation")); CHECK_EQ(checkPath(0, { "sleep" }), std::string("step 1: unknown operation"));
}

